/// Binary search over the id-sorted table.
pub fn profile(id: &str) -> Option<&'static CombatProfile> {
    PROFILES
        .binary_search_by(|probe| probe.id.cmp(id))
        .ok()
        .map(|index| &PROFILES[index])
}
